from __future__ import annotations

from pgvector.sqlalchemy import VECTOR
from sqlalchemy import ARRAY, Boolean, Column, DateTime, Float, ForeignKey, Integer, Table, Text, UniqueConstraint, func
from sqlalchemy.dialects.postgresql import JSONB, UUID

from ai_scientist.research_store.models import metadata


SCHEMA = "literature"


def _id(name: str) -> Column:
    return Column(name, UUID(as_uuid=False), primary_key=True)


def _created() -> Column:
    return Column("created_at", DateTime(timezone=True), nullable=False, server_default=func.now())


venues = Table("venues", metadata, _id("venue_id"), Column("code", Text, nullable=False, unique=True), Column("name", Text, nullable=False), Column("field", Text), Column("policy", JSONB, nullable=False, server_default="{}"), _created(), schema=SCHEMA)
