papers = Table("papers", metadata, _id("paper_id"), Column("title", Text, nullable=False), Column("normalized_title", Text, nullable=False), Column("abstract", Text, nullable=False, server_default=""), Column("publication_year", Integer), Column("status", Text, nullable=False, server_default="ACTIVE"), _created(), Column("updated_at", DateTime(timezone=True), nullable=False, server_default=func.now(), onupdate=func.now()), schema=SCHEMA)
