sections = Table("sections", metadata, _id("section_id"), Column("document_id", UUID(as_uuid=False), ForeignKey("literature.documents.document_id"), nullable=False), Column("section_type", Text, nullable=False), Column("heading", Text), Column("ordinal", Integer, nullable=False), Column("page_start", Integer), Column("page_end", Integer), Column("char_start", Integer, nullable=False), Column("char_end", Integer, nullable=False), Column("content_hash", Text, nullable=False), schema=SCHEMA)
